import sys

def get_days_in_month(month, year):
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 28

def main():
    prophesy = sys.stdin.readline().strip()
    counts = {}

    n = len(prophesy)
    for i in range(n - 10):
        substring = prophesy[i:i+10]
        if len(substring) != 10:
            continue

        parts = substring.split('-')
        if len(parts) != 3:
            continue

        d_str, m_str, y_str = parts
        if not (d_str.isdigit() and m_str.isdigit() and y_str.isdigit()):
            continue
        if len(d_str) != 2 or len(m_str) != 2 or len(y_str) != 4:
            continue

        try:
            day = int(d_str)
            month = int(m_str)
            year = int(y_str)
        except ValueError:
            continue

        if not (2013 <= year <= 2015):
            continue
        if not (1 <= month <= 12):
            continue
        if not (1 <= day <= get_days_in_month(month, year)):
            continue

        key = (day, month, year)
        counts[key] = counts.get(key, 0) + 1

    best_date = None
    best_count = -1

    for date_tuple, count in counts.items():
        if count > best_count:
            best_count = count
            best_date = date_tuple

    day, month, year = best_date
    print(f"{day:02d}-{month:02d}-{year}")

if __name__ == "__main__":
    main()
